<template>
  <label
    class="fu-radio"
    :class="[
      `fu-radio--${size}`,
      variant ? `fu-radio--${variant}` : null,
      {
        'is-checked': isChecked,
        'is-disabled': disabled,
        'is-readonly': readonly,
      },
    ]"
    :style="typeformStyle"
  >
    <input
      type="radio"
      class="fu-radio__input"
      :value="value"
      :disabled="disabled"
      :checked="isChecked"
      :aria-readonly="readonly"
      @click="handleClick"
      @change="handleChange"
    />

    <!-- Outer Circle -->
    <span class="fu-radio__control">
      <span class="fu-radio__dot" v-if="isChecked" />
    </span>

    <!-- Label -->
    <span v-if="$slots.default" class="fu-radio__label">
      <slot />
    </span>
  </label>
</template>

<script setup lang="ts">
import { computed } from "vue";

type Size = "xs" | "sm" | "md" | "lg" | "xl";
type Variant = "default" | "typeform";

interface Props {
  modelValue?: string | number;
  value: string | number;
  size?: Size;
  variant?: Variant;
  disabled?: boolean;
  readonly?: boolean;

  /* TYPEFORM VARIANT STYLING — same idea as FusionTextInput/FusionTextArea */
  font?: string;
  fontSize?: string;
  color?: string;
}

const props = withDefaults(defineProps<Props>(), {
  size: "md",
  variant: "default",
  disabled: false,
  readonly: false,
  font: undefined,
  fontSize: undefined,
  color: undefined,
});

const emit = defineEmits(["update:modelValue"]);

const model = computed<string | number>({
  get: () => props.modelValue as string | number,
  set: (val: string | number) => emit("update:modelValue", val),
});

const isChecked = computed(() => model.value === props.value);

const typeformStyle = computed(() => {
  if (props.variant !== "typeform") return {};
  return {
    ...(props.font ? { "--fu-typeform-font": props.font } : {}),
    ...(props.fontSize ? { "--fu-typeform-font-size": props.fontSize } : {}),
    ...(props.color ? { "--fu-typeform-color": props.color } : {}),
  };
});

/* -----------------------------------------------------------
   Readonly handling
   Native <input type="radio"> has no real "readonly" behavior —
   browsers silently ignore the readonly attribute on radios/checkboxes,
   so it has to be enforced manually: block the click before the browser
   toggles the native checked state, and never emit update:modelValue.
   disabled still uses the native :disabled attribute as before.
----------------------------------------------------------- */

function handleClick(e: MouseEvent) {
  if (props.readonly) {
    e.preventDefault();
  }
}

function handleChange() {
  if (props.readonly) return;
  emit("update:modelValue", props.value);
}
</script>

<style scoped lang="scss">
.fu-radio {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  cursor: pointer;
  position: relative;

  &__input {
    display: none;
  }

  &__control {
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    border: 2px solid #9ca3af;
    transition: all 0.2s ease;
    background: transparent;
  }

  &__dot {
    border-radius: 50%;
    background: #3b82f6;
    transition: all 0.2s ease;
  }

  &__label {
    font-weight: 500;
  }

  /* Sizes */
  &--xs &__control {
    width: 14px;
    height: 14px;
  }
  &--xs &__dot {
    width: 6px;
    height: 6px;
  }

  &--sm &__control {
    width: 18px;
    height: 18px;
  }
  &--sm &__dot {
    width: 8px;
    height: 8px;
  }

  &--md &__control {
    width: 22px;
    height: 22px;
  }
  &--md &__dot {
    width: 10px;
    height: 10px;
  }

  &--lg &__control {
    width: 26px;
    height: 26px;
  }
  &--lg &__dot {
    width: 12px;
    height: 12px;
  }

  &--xl &__control {
    width: 32px;
    height: 32px;
  }
  &--xl &__dot {
    width: 14px;
    height: 14px;
  }

  /* Checked state */
  &.is-checked &__control {
    border-color: #3b82f6;
  }

  /* Disabled */
  &.is-disabled {
    opacity: 0.5;
    cursor: not-allowed;
  }

  /* Readonly — visible and focusable like a normal radio, just not
     clickable. No opacity/greyscale change (that's disabled's job) so
     it doesn't look "broken", just non-interactive. */
  &.is-readonly {
    cursor: default;
  }

  /* ── Typeform variant ──
     Label text picks up the document theme's font/fontSize/color; the
     dot + border only switch to the theme color once checked, so an
     unselected option still reads as a normal neutral radio. */
  &--typeform &__label {
    font-family: var(--fu-typeform-font, inherit);
    font-size: var(--fu-typeform-font-size, inherit);
    color: var(--fu-typeform-color, inherit);
  }

  &--typeform.is-checked &__control {
    border-color: var(--fu-typeform-color, #3b82f6);
  }

  &--typeform &__dot {
    background: var(--fu-typeform-color, #3b82f6);
  }
}
</style>
