<template>
  <div class="fu-tag-input-wrapper">
    <label v-if="label" class="fu-tag-input-label">{{ label }}</label>

    <div
      class="fu-tag-input"
      :class="{ 'is-focused': isFocused, 'fu-tag-input--error': !!error }"
      @click="focusInput"
    >
      <span v-for="(tag, i) in modelValue" :key="tag" class="fu-tag-chip">
        {{ tag }}
        <button
          type="button"
          class="fu-tag-chip__remove"
          :disabled="readonly || disabled"
          @click.stop="removeTag(i)"
        >
          <X :size="12" />
        </button>
      </span>

      <input
        ref="inputRef"
        v-model="draft"
        class="fu-tag-input__field"
        :placeholder="modelValue.length ? '' : placeholder"
        :disabled="disabled"
        :readonly="readonly"
        @keydown.enter.prevent="commitDraft"
        @keydown="handleKeydown"
        @focus="isFocused = true"
        @blur="handleBlur"
      />
    </div>

    <p v-if="hint" class="fu-tag-input-hint">
      <Lightbulb :size="14" />
      <span>{{ hint }}</span>
    </p>

    <span v-if="error" class="fu-tag-input-error">{{ error }}</span>
    <span v-else-if="helperText" class="fu-tag-input-helper">{{ helperText }}</span>
  </div>
</template>

<script setup lang="ts">
import { ref, computed } from "vue";
import { X, Lightbulb } from "lucide-vue-next";

interface Props {
  modelValue?: string[];
  label?: string;
  placeholder?: string;
  hint?: string;
  helperText?: string;
  disabled?: boolean;
  readonly?: boolean;
  /** "email" runs basic email-shape validation before a tag is accepted */
  validate?: "email" | ((value: string) => boolean);
  error?: string | null;
}

const props = withDefaults(defineProps<Props>(), {
  modelValue: () => [],
  label: "",
  placeholder: "Press ENTER to add",
  hint: "",
  helperText: "",
  disabled: false,
  readonly: false,
  validate: undefined,
  error: null,
});

const emit = defineEmits<{
  (e: "update:modelValue", value: string[]): void;
  (e: "invalid", value: string): void;
}>();

const draft = ref("");
const isFocused = ref(false);
const inputRef = ref<HTMLInputElement | null>(null);

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function isValid(value: string) {
  if (!props.validate) return true;
  if (props.validate === "email") return EMAIL_RE.test(value);
  return props.validate(value);
}

function focusInput() {
  if (props.disabled) return;
  inputRef.value?.focus();
}

function commitDraft() {
  const value = draft.value.trim().replace(/,$/, "");
  if (!value) return;

  if (!isValid(value)) {
    emit("invalid", value);
    return;
  }

  if (!props.modelValue.includes(value)) {
    emit("update:modelValue", [...props.modelValue, value]);
  }
  draft.value = "";
}

function handleKeydown(e: KeyboardEvent) {
  // Comma also commits a tag, same as Enter — common pattern for email/tag fields
  if (e.key === ",") {
    e.preventDefault();
    commitDraft();
    return;
  }
  if (e.key === "Backspace") {
    handleBackspace();
  }
}

function handleBackspace() {
  if (draft.value === "" && props.modelValue.length) {
    removeTag(props.modelValue.length - 1);
  }
}

function handleBlur() {
  isFocused.value = false;
  // Commit whatever's typed when focus leaves, so a value isn't silently lost
  if (draft.value.trim()) commitDraft();
}

function removeTag(index: number) {
  if (props.readonly || props.disabled) return;
  const next = [...props.modelValue];
  next.splice(index, 1);
  emit("update:modelValue", next);
}
</script>

